 public static void save(Object e,Object nbt){R.call(nbt,"putInt",P+"state",state(e));}
 public static Rules.Weapon weapon(Object bullet){Object id=R.get(bullet,"gunId");if(id==null)return Rules.Weapon.OTHER;Object optional=R.call(R.type("com.tacz.guns.api.TimelessAPI"),"getCommonGunIndex",id);if(!R.yes(R.call(optional,"isPresent")))return Rules.Weapon.OTHER;return Rules.weapon(R.call(R.call(optional,"get"),"getType").toString());}
 public static void begin(Object bullet,Object hit){Object entity=R.call(hit,"getEntity");if(zombie(entity))shots.set(new Shot(bullet,entity,R.call(hit,"getLocation"),R.yes(R.call(hit,"isHeadshot")),weapon(bullet)));}
