 public static void hurt(Object event){Object e=R.call(event,"getEntity");if(!zombie(e)||R.yes(R.get(R.call(e,"level"),"isClientSide")))return;Shot shot=shots.get();if(shot==null||shot.entity!=e||R.call(R.call(event,"getSource"),"getDirectEntity")!=shot.bullet)return;float amount=((Number)R.call(event,"getNewDamage")).floatValue();if(amount<=0)return;push(e,shot.bullet,shot.gun);Object pos=R.call(e,"position");double y=(R.num(R.get(shot.point,"y"))-R.num(R.get(pos,"y")))/R.num(R.call(e,"getBbHeight"));double yaw=Math.toRadians(R.num(R.call(e,"getYRot"))),dx=R.num(R.get(shot.point,"x"))-R.num(R.get(pos,"x")),dz=R.num(R.get(shot.point,"z"))-R.num(R.get(pos,"z"));int zone=Rules.zone(y,dx*Math.cos(yaw)+dz*Math.sin(yaw),shot.head);Object tag=tag(e);float total=((Number)R.call(tag,"getFloat",P+"damage_"+zone)).floatValue()+amount;R.call(tag,"putFloat",P+"damage_"+zone,total);set(e,Rules.update(state(e),zone,amount,total,((Number)R.call(e,"getMaxHealth")).floatValue(),shot.gun));}
 public static void push(Object entity,Object bullet,Rules.Weapon gun){Object data=tag(entity);int tick=((Number)R.get(entity,"tickCount")).intValue();if(R.yes(R.call(data,"contains",P+"push_tick"))&&((Number)R.call(data,"getInt",P+"push_tick")).intValue()==tick)return;Object motion=R.call(bullet,"getDeltaMovement");double x=R.num(R.get(motion,"x")),z=R.num(R.get(motion,"z")),length=Math.hypot(x,z);if(length<.0001)return;R.call(data,"putInt",P+"push_tick",tick);double strength=Rules.push(gun);R.call(entity,"push",x/length*strength,.005,z/length*strength);R.set(entity,"hurtMarked",true);R.set(entity,"hasImpulse",true);}
 public static void incoming(Object event){Object source=R.call(event,"getSource"),attacker=R.call(source,"getDirectEntity");if(!zombie(attacker)||attacker!=R.call(source,"getEntity"))return;double factor=Rules.attack(state(attacker));if(factor!=1)R.call(event,"setAmount",(float)(R.num(R.call(event,"getAmount"))*factor));}
 static void modifier(Object e,String attribute,String id,double scale){Object field=R.get(R.type("net.minecraft.world.entity.ai.attributes.Attributes"),attribute),instance=R.call(e,"getAttribute",field);if(instance==null)return;Object key=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_gore",id);R.call(instance,"removeModifier",key);if(scale!=1)R.call(instance,"addTransientModifier",R.make("net.minecraft.world.entity.ai.attributes.AttributeModifier",key,scale-1,R.get(R.type("net.minecraft.world.entity.ai.attributes.AttributeModifier$Operation"),"ADD_MULTIPLIED_TOTAL")));}
